T["Code.eeed48c1"] = "Сховати повідомлення про помилки"
T["Code.f7dfb971"] = "Ховає червоні повідомлення посеред екрана."
T["Code.e92659f5"] = "Повідомлення на кшталт \"Поза зоною дії\" чи \"Недостатньо люті\" більше не показуються. Показуються й надалі: повний інвентар або сумки, повний журнал завдань, брак грошей, забагато екземплярів предмета при собі."
T["Code.b0776bbf"] = "Перетягуйте вікна, як-от вікно персонажа чи журналу завдань, куди завгодно."
T["Code.0dea12ef"] = "Перетягуйте вікна, як-от вікно персонажа, торговця чи журналу завдань, лівою кнопкою миші. Позиції запам'ятовуються."
T["Code.892c796b"] = "Переміщені вікна Blizzard повертаються на своє місце за замовчуванням."
T["Code.25a4eccd"] = "Утримуйте Ctrl і праву кнопку миші на вікні, як-от вікно персонажа чи журналу завдань, і тягніть: праворуч або вниз робить його більшим, ліворуч або вгору меншим (50 - 150 %). Розмір показується біля курсора й запам'ятовується."
T["Code.420915e0"] = "Вікна Blizzard зі зміненим розміром повертаються до звичайного розміру."
T["Code.395e9223"] = "Також кнопка збирача кнопок мінікарти."
T["Code.5b5513be"] = "Панель відкривається з більшої кнопки OneForAll, яку можна перетягнути куди завгодно (вона не прив'язана до мінікарти). Правий клік по цій кнопці відкриває OneForAll. Якщо це вимкнути, усі кнопки повернуться на мінікарту. Не разом із \"Сховати кнопку OneForAll\"."
T["Code.a66d3caa"] = "Повертає збирач кнопок мінікарти на його місце за замовчуванням біля мінікарти."
T["Code.194f3edf"] = "Панель відкривається"
T["Code.9305f4ea"] = "Де відкривається панель біля кнопки OneForAll."
T["Code.348e649e"] = "Автоматично: у бік середини екрана."
T["Code.438b027e"] = "Сховати кнопку OneForAll"
T["Code.afc4ef4f"] = "Без кнопки OneForAll біля мінікарти."
T["Code.59c62a94"] = "Відкривайте OneForAll зі списку аддонів гри біля мінікарти або командою /ofa. Не разом із \"Збирати кнопки мінікарти\": панель потребує своєї кнопки."
T["Code.47613f08"] = "Перемістити мінікарту"
T["Code.9034c6f7"] = "Скористайтеся режимом редагування гри: Меню гри > Режим редагування, потім перетягніть мінікарту."
T["Code.77b92648"] = "OneForAll більше сам не переміщує мінікарту: він конфліктував із режимом редагування, мінікарта стрибала назад, і її вже не можна було пересунути."
T["Code.2bb4a192"] = "Кругла рамка та компас сховані; кнопки мінікарти інших аддонів слідують за квадратним краєм. Нічого не робить з ElvUI або коли інший аддон уже робить мінікарту квадратною."
T["Code.57d55a67"] = "Встановіть менше за 10, щоб вимкнути (тоді зберігається власне налаштування гри)."
T["Code.3ea5a5dc"] = "Кнопка копіювання чату"
T["Code.1fbfd045"] = "Додає до кожного вікна чату кнопку для копіювання його тексту."
T["Code.b12ccc4e"] = "Невелика кнопка вгорі праворуч у кожному вікні чату. Вона відкриває текст чату, щоб ви могли виділити й скопіювати його (Ctrl+C)."
T["Code.ad935f1b"] = "Кнопка приховування чату"
T["Code.e66a50e4"] = "Кнопка біля чату ховає й показує його."
T["Code.6a0168f1"] = "Сховати чат через"
T["Code.43c34ed8"] = "Ховає чат після такого часу без нового повідомлення."
T["Code.0cf2e12c"] = "Нове повідомлення або введення тексту показує його знову. Не тоді, коли миша на чаті."
T["Code.a3a94a9c"] = "Історія повідомлень"
T["Code.6e7e93d1"] = "Стрілка вгору / вниз у полі чату повертає ваші останні 5 повідомлень."
T["Code.515d4b11"] = "Введіть, надішліть, знову відкрийте чат і натисніть стрілку вгору: повідомлення знову тут, Enter надсилає його. Під час введення стрілки більше не повертають вашого персонажа."
T["Code.a96f5500"] = "Копіювати чат"
T["Code.31c6be9a"] = "Ctrl+C копіює виділений текст.  Esc закриває."
T["Code.669bdbfc"] = "Автозбір здобичі"
T["Code.b6c6bcf1"] = "Власне налаштування гри \"Автозбір здобичі\"."
T["Code.60b22be0"] = "Те саме, що Параметри > Керування > Автозбір здобичі."
T["Code.137c2749"] = "Замість збору предмет за предметом."
T["Code.a7c9acf9"] = "Список мотлоху"
T["Code.4ce4d074"] = "Список цього персонажа. Продаж мотлоху продає й ці предмети."
T["Code.3fe93876"] = "Продаж мотлоху більше не продаватиме цей предмет."
T["Code.478211e4"] = "Прибрати всі предмети зі списку мотлоху?"
T["Code.8e457848"] = "Пропонує найдешевший предмет у ваших сумках (вартість x стос), знищує його і забирає здобич одним кліком. Предмети завдань, бібліотечні книги, рецепти, частини комплектів, інструменти професій і предмети без вартості ніколи не пропонуються. Предмети кращі за сірі потребують другого кліку. /ofa cheapest показує його будь-коли."
T["Code.f2c3e0f4"] = "Лише сірі та білі предмети"
T["Code.972f51a9"] = "Помічник пропонує лише погані та звичайні предмети."
T["Code.c2000190"] = "Ніколи не пропонувати"
T["Code.21aab4ef"] = "Предмети, які ви заблокували кнопкою X у помічнику."
T["Code.c87c1a9c"] = "Відкрийте список, щоб знову дозволити окремі предмети, або приберіть усі."
T["Code.ec86f3cf"] = "Список порожній. У помічнику повних сумок кнопка X додає предмет сюди, щоб його більше ніколи не пропонували."
T["Code.313c06b4"] = "Помічник повних сумок знову може пропонувати цей предмет."
T["Code.e5e6a9ce"] = "Прибрати всі предмети зі списку\n\"ніколи не пропонувати\"?"
T["Code.9e088660"] = "Як текст бою, що прокручується."
T["Code.069d27aa"] = "Мінімальна якість"
T["Code.bf8b1767"] = "Предмети нижчої якості не показуються."
T["Code.631ea32e"] = "Показувати гроші"
T["Code.0f89e005"] = "Також показує зібрані гроші."
T["Code.c4b4de9a"] = "Позиція"
T["Code.df557bf0"] = "Перемістіть стрічку, покажіть приклади записів або поверніть її на місце."
T["Code.ab6f4c2f"] = "Повертає стрічку здобичі на стандартне місце праворуч від вашого персонажа."
T["Code.1a1b7ae6"] = "Показує кілька прикладів записів."
T["Code.5e89ed55"] = "Показує область стрічки здобичі. Перетягніть її, куди потрібно, потім натисніть \"Закріпити\"."
T["Code.628826b4"] = "Перетягніть, щоб перемістити, потім натисніть \"Закріпити\" на вкладці \"Зручності\""
T["Code.e8badb36"] = "Трава або рудна жила поруч із вами виблискує."
T["Code.0cf28cc1"] = "Обережно!"
T["Code.d6ba90be"] = "Цей параметр змінює м'яке націлювання, прочитайте підказку!"
T["Code.c8740425"] = "Приймає завдання, коли ви розмовляєте з тим, хто їх видає. Утримуйте Shift, щоб робити це вручну."
T["Code.6a14a7d1"] = "Здає виконані завдання. Утримуйте Shift, щоб робити це вручну."
T["Code.a1c8d825"] = "Якщо можна вибрати нагороду, ви все одно обираєте самі."
T["Code.eaedca9e"] = "Показує досвід за виконані завдання на смузі досвіду."
T["Code.8ddcdd24"] = "Позначає на смузі досвіду, скільки досвіду дадуть виконані завдання, коли ви їх здасте. Кількість також видно в підказці смуги."
T["Code.5438f58b"] = "Найвища ціна продажу серед нагород"
T["Code.b4d3b9a2"] = "Золота монета на нагороді за завдання, яку можна продати найдорожче."
T["Code.54f97915"] = "У журналі завдань і коли ви здаєте завдання з двома чи більше нагородами на вибір: та, що має найвищу ціну в торговця (помножену на кількість), отримує золоту монету у верхньому правому куті. Зелена стрілка покращення лишається вгорі ліворуч, тож предмет може мати обидві."
T["Code.37d43301"] = "Сяйво здобичі з гри. Ті, хто видає завдання, та деякі інші NPC теж сяють: це частина цього налаштування гри. Змінює лише це одне налаштування, ваші налаштування контуру лишаються як є. Після вимкнення перезапустіть гру."
T["Code.d721e669"] = "Меч: його потрібно вбити для завдання. Сумка: з нього випадає предмет завдання. З прогресом (3/10); нічого, коли цю частину виконано. Використовує рядки завдань, які гра показує в підказці ворога. Ще не працює всередині підземель."
T["Code.4d454345"] = "Позиція позначки"
T["Code.6ea81f24"] = "Перетягніть позначку туди, де хочете, на табличці імені."
T["Code.ca4f45c4"] = "Здобич з босів"
T["Code.8a42fc27"] = "Показує, з якого боса підземелля випадає предмет."
T["Code.6705c721"] = "Цінність спорядження"
T["Code.07322a1a"] = "Покращення або погіршення у % порівняно з тим, що на вас надіто."
T["Code.2b2ffb67"] = "На спорядженні, яке ви можете використовувати: наскільки воно краще (зелений) або гірше (червоний) за те, що на вас, з урахуванням вашої спеціалізації, як в Арсенал > Планувальник спорядження. Також зелена стрілка на покращеннях у ваших сумках, у вікні розіграшу здобичі та серед нагород за завдання," ..
	" і золота зірка для предметів зі списку бажань (/ofa rolltest показує приклад)."
T["Code.4745438d"] = "Колір стрілки за типом броні"
T["Code.0e488ea6"] = "Жовта стрілка для покращень у легшому типі броні."
T["Code.c76ce6a5"] = "Зелена стрілка лишається для покращень у найкращому типі броні вашого класу. Покращення в легшому типі отримують жовту стрілку: воїни та паладини носять лати з 40 рівня (до цього кольчугу), мисливці та шамани кольчугу з 40 (до цього шкіру), розбійники та друїди шкіру. Плащі, прикраси, щити та зброя не зачіпаються. Потребує \"Цінність спорядження\"."
T["Code.cbfff147"] = "Рецепти: хто їх знає"
T["Code.7ff7dbbd"] = "Чи знаєте рецепт ви, ваш твінк або учасник гільдії."
T["Code.018c2ad2"] = "Вимкнути автоматичну підказку порівняння"
T["Code.b33e4c81"] = "Утримуйте Shift, щоб побачити ваш одягнений предмет поруч із підказкою."
T["Code.0ba4a5a9"] = "Підказки предметів більше не показують ваш одягнений предмет поруч автоматично."
T["Code.5f42f39b"] = "Завдання в NPC"
T["Code.4d41cffc"] = "Завдання, які можна взяти (!) або здати (?) в NPC під вашою мишею."
T["Code.a04f0567"] = "Ті самі завдання, що й значки завдань на карті світу: для вашого рівня, сторони, раси та класу, з виконаними попередніми завданнями. Вимкнено, поки завантажено Questie (він показує свої)."
T["Code.60ca51a1"] = "Ціль гравців"
T["Code.b2b156fc"] = "Показує, кого обрав ціллю гравець або NPC під вашою мишею."
T["Code.3a8b885c"] = "\"Ви\", коли це ви."
T["Code.ea053b9b"] = "Випадає з:"
T["Code.1c4c5d91"] = "Ви знаєте цей рецепт"
T["Code.631ba45f"] = "Твінки:"
T["Code.b5fde8b4"] = "Гільдія:"
T["Code.0b883c42"] = "Ви"
T["Code.30691306"] = "Ціль:"
T["Code.0f597a68"] = "Запрошення до групи від"
T["Code.e1205c18"] = "Приймає запрошення до групи від гравців, яких ви оберете."
T["Code.133725ea"] = "Вимкнено: OneForAll нічого не робить із запрошеннями."
T["Code.99dfa560"] = "Запрошення за ключовим словом від"
T["Code.835395a8"] = "Запрошує гравців, які шепнуть вам ключове слово."
T["Code.7db5373d"] = "Вимкнено: OneForAll нічого не робить із шепотами."
T["Code.85792eca"] = "Ключове слово"
T["Code.3baebd10"] = "Слово, яке гравці шепочуть вам, щоб отримати запрошення."
T["Code.1eba10f5"] = "Дозволяти дуелі від"
T["Code.0fc40e93"] = "Запити на дуель від усіх інших відхиляються."
T["Code.9e4de305"] = "Вимкнено: OneForAll нічого не робить із дуелями."
T["Code.4e653fb5"] = "Ділитися рецептами з іншими користувачами OneForAll"
T["Code.30e4b642"] = "Знаходить користувачів OneForAll поза вашою гільдією, які знають рецепт."
T["Code.31d2ed14"] = "Кнопка пошуку біля рецепта в Професії > Усі рецепти питає інших користувачів OneForAll, які його знають (синя позначка); відповідають лише кілька з них, тож це лишається швидким і з багатьма гравцями. Коли вимкнено, вас не питають і ви теж не шукаєте. Учасники гільдії завжди ділять рецепти. Перенесено сюди з Налаштувань у 6.1.0."
T["Code.16a5dcc7"] = "Для бафів, що тривають довше 2 хвилин. Надходить через 1 секунду, не в бою, не частіше ніж раз на 5 хвилин для кожного гравця. Вашу ціль не змінюють. /ofa thanks показує останні бафи."
T["Code.51359af5"] = "Прийнято запрошення до групи від %s."
S["Code.51359af5"] = "f"
T["Code.615a1562"] = "Відхилено дуель від %s."
S["Code.615a1562"] = "f"
T["Code.9c9b8ea5"] = "Входи в підземелля, майстри польотів, кораблі, трамвай і бібліотечні книги на карті."
T["Code.0c1ada63"] = "Ваша фракція та нейтральні. Натисніть на вхід, щоб відкрити це підземелля в OneForAll. Цепеліни, кораблі, трамвай і майстри польотів показують, куди вони ведуть."
T["Code.2ce32bff"] = "Переходи між зонами"
T["Code.143345cc"] = "Вказівник там, де дорога веде до наступної зони."
T["Code.8063e1ad"] = "Підказка називає іншу зону; клік показує її на карті. Місця з аддона Carbonite (GPL)."
T["Code.a26fa1e2"] = "Значок книги там, де лежить кожна бібліотечна книга, яка вам ще потрібна."
